static void draw_strength_badges(void){SDL_SetRenderDrawBlendMode(renderer,SDL_BLENDMODE_BLEND);nquad=0;for(int i=0;i<MAXE;i++){Obj*o=g.enemies+i;if(!o->on||o->strength<1||o->type==4||enemy_organic(o)||!enemy_in_view(o))continue;int n=o->strength;float x=o->x/(float)Q,y=o->y/(float)Q-pc_enemy_radius(o)*.55f-5;SDL_FColor colour=n==1?(SDL_FColor){.3f,1,.55f,.9f}:n==2?(SDL_FColor){1,.86f,.25f,.9f}:(SDL_FColor){1,.35f,.3f,.9f};for(int pip=0;pip<n;pip++){float xx=x+(pip-(n-1)*.5f)*3.5f;quad((xx-1.7f)*3,(y-1.7f)*3,10.2f,10.2f,(SDL_FColor){.015f,.025f,.035f,.8f},0,0,0,0);quad((xx-1)*3,(y-1)*3,6,6,colour,0,0,0,0);}}flush(NULL);}
